/* Keep autogenerated Studio poster headings in sync with selected subject.
 * No new text layers and no changes to user-edited copy. */
(() => {
  let attempts=0;
  function boot(){
    const s=window.__cerebra?.studio;
    if(!s?.presetTexts||!s?.select||!s?.setSubject){
      if(++attempts<180)setTimeout(boot,200);
      return;
    }
    if(s.__modelPresetTitleReady)return;
    s.__modelPresetTitleReady=true;
    const names={f9:'Falcon 9',fh:'Falcon Heavy',sv:'Saturn V'};
    const autoMission=new WeakMap();
    let recentRocket=null,preferWorld=false;
    const worldName=()=>s.subject>=0
      ?s.app?.orrery?.worlds?.[s.subject]?.def?.name||'Cerebra'
      :'Cerebra';
    const chooseName=()=>{
      if(preferWorld)return worldName();
      const valid=it=>it&&s.items.includes(it)&&it.kit==='rocket'&&!it.hide&&!it.deleted;
      const selected=valid(s.sel)?s.sel:null;
      if(selected)recentRocket=selected;
      const rocket=selected||(valid(recentRocket)?recentRocket:null)
        ||s.items.slice().reverse().find(valid);
      return rocket?(rocket.name||names[rocket.p?.model]||worldName()):worldName();
    };
    const apply=()=>{
      if(!s.active)return false;
      const name=chooseName(),study=name+' / studio study';
      let changed=false;
      for(const it of s.items){
        if(it.kind!=='text'||it.edited||!it.el?.isConnected||it.el.isContentEditable)continue;
        let value=null;
        if(it.role==='title')value=name;
        else if(it.role==='kicker')value=study;
        else if(!it.role&&it.missionLayout&&it.tpl&&/^rocket/i.test(it.tpl)){
          const old=autoMission.get(it);
          if(it.content==='CEREBRA / STUDIO STUDY'||it.content===old){
            value=name.toUpperCase()+' / STUDIO STUDY';
            autoMission.set(it,value);
          }
        }
        if(value!==null&&it.content!==value){
          it.content=value;it.el.textContent=value;s.place(it);changed=true;
        }
      }
      if(changed){s.renderLayers();s.commitSoon?.();}
      return changed;
    };
    const nativeSelect=s.select;
    s.select=function(it,...args){
      const value=nativeSelect.call(this,it,...args);
      if(it?.kit==='rocket'){recentRocket=it;preferWorld=false;}
      apply();
      return value;
    };
    const nativePreset=s.presetTexts;
    s.presetTexts=function(...args){
      const value=nativePreset.apply(this,args);
      apply();
      return value;
    };
    const nativeSubject=s.setSubject;
    s.setSubject=function(...args){
      const value=nativeSubject.apply(this,args);
      preferWorld=true;recentRocket=null;apply();
      return value;
    };
    if(window.CerebraMissionPresets?.apply){
      const mission=window.CerebraMissionPresets,base=mission.apply;
      mission.apply=function(...args){const value=base.apply(this,args);apply();return value;};
    }
    window.CerebraModelPresetTitles={sync:apply,current:chooseName};
  }
  boot();
})();